function writeMessagesFile(filepath, data) {
  process.nextTick(function () {
    async.series([
      function(callback) {
        mkdirp(path.dirname(filepath), callback);
      },
      function(callback) {
        fs.writeFile(filepath, stringify(data, { space: 2 }), callback);
      }
    ]);
  });
}

